item.text:
{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated testing is undocumented; silence does not establish whether it occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score cannot establish consistency across runs."
        }
      ],
      "instrument_review": "Exact-grid scoring and the narrow intended use support interpreting the reported puzzle performance. Repeat-run consistency is unknown, and the supplied information does not establish fair comparison procedures."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated-run testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "Without repeated observations, score stability remains unknown; instability is not demonstrated either."
        }
      ],
      "instrument_review": "The score describes one evaluation on the specified puzzles. The documented absence of repetition limits consistency claims, while the narrow intended interpretation remains appropriate."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated evaluations explicitly held the stated conditions constant."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's definition of stability: at most two percentage points."
        }
      ],
      "instrument_review": "Controlled repetitions support score consistency under the specified conditions and stated stability criterion. They do not establish consistency for different puzzles, systems, or settings."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The passage explicitly documents repeated testing under the same conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the report's stability limit of two percentage points."
        }
      ],
      "instrument_review": "The repetitions document substantial inconsistency under fixed conditions. Reporting 70% alone would inadequately represent the observed variation and weaken comparisons based on a single run."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions provide no evidence that repeated evaluations occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added documentation supplies no observations of score consistency."
        }
      ],
      "instrument_review": "Installation guidance documents setup but adds no evidence about score stability or fair comparisons. Interpretation remains limited to the reported puzzle evaluation."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A achieved the higher exact-grid result on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The evidence does not establish comparative general intelligence across domains."
        }
      ],
      "instrument_review": "The narrow intended use matches the tested content and supports the reported performance ordering. Fixed instructions aid comparability, but other resource controls and repeated-run consistency are unspecified."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported results show higher puzzle performance for A."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A stated cross-domain purpose does not supply evidence of cross-domain ability."
        }
      ],
      "instrument_review": "The intended selection use exceeds the evidence: grid-only results support a puzzle comparison but do not establish greater general intelligence across domains. Broader interpretation lacks supporting findings."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone do not establish comparative effects on real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "Random allocation, blinded correctness checks, and a positive reported uncertainty interval support better correctness with A in the studied conditions."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Unmeasured safety outcomes cannot be inferred from decision correctness alone."
        }
      ],
      "instrument_review": "The later preregistered randomized trial provides direct evidence relevant to choosing assistance for correct decisions in this workshop. The reported uncertainty supports the correctness difference; transfer to other workshops and effects on time or safety remain unestablished."
    }
  ],
  "closing_note": "No material instruction ambiguity affected the review. Missing evidence was distinguished from explicit contradiction, and each case was assessed independently."
}
